{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C11"],
      "claim": "A close aryl-piperazine amide analog showed brain-to-serum AUC and Cmax ratios >1 in mice after both i.p. and p.o. dosing, directly demonstrating robust CNS access for the same piperazine-amide scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "The benzamide basic-amine analog AH-7921 achieved a brain-to-plasma ratio of 16.6 in rat acute PK and was classified as having good brain penetrability, supporting meaningful CNS access for the query's benzamide-ethylamine motif.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Hydroxybupropion gave a Kp,uu of 1.7 by quantitative microdialysis in rats, showing rapid equilibration and unbound brain exposure above plasma; this direct unbound-brain measurement supports CNS access despite moderate polarity.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "An aryl-piperazine bis-amide readily passed the BBB with high brain and spinal cord levels in mice, reinforcing that piperazine-amide chemotypes like the query are CNS-penetrant.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "A radioiodinated benzamide analog accumulated significantly in monkey brain by planar imaging, providing primate evidence that the benzamide-amine scaffold crosses the BBB.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "High-transfer in vivo evidence from close aryl-piperazine/benzamide analogs consistently shows robust brain penetration (brain-to-plasma ratios >1, Kp,uu 1.7, brain accumulation in rodents and monkey), and the query's physicochemical profile is favorable; therefore meaningful CNS access is predicted.",
  "evidence_gaps": [
    "No direct experimental measurement for the exact query molecule; predictions rely on close analogs.",
    "P-gp/BCRP efflux status of the query is not experimentally confirmed, although the physicochemical prior and analog data suggest low risk.",
    "No human CSF or PET data for the query; primate evidence is from a close iodinated analog."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

